css:
.crumbs .sp .focus-timer {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-right: 4px;
  font: inherit;
  color: currentColor;
  font-variant-numeric: tabular-nums;
}
.crumbs .sp .focus-timer button {
  font: inherit;
  color: inherit;
}

js:
morse.watch("body > div.pg > div.crumbs > span.sp", el => {
  if (el.querySelector(".focus-timer")) return;
  let remaining = 25 * 60;
  let running = false;
  let handle = null;

  const label = morse.el("span", { text: "25:00" });
  const toggle = morse.el("button", { text: "▶", title: "Start focus timer" });

  const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
  const render = () => { label.textContent = fmt(remaining); };

  const stop = () => {
    running = false;
    clearInterval(handle);
    handle = null;
    toggle.textContent = "▶";
    toggle.title = "Start focus timer";
  };

  const start = () => {
    if (remaining <= 0) remaining = 25 * 60;
    running = true;
    toggle.textContent = "❚❚";
    toggle.title = "Pause focus timer";
    handle = setInterval(() => {
      remaining -= 1;
      render();
      if (remaining <= 0) {
        stop();
        morse.toast("Focus session complete");
      }
    }, 1000);
  };

  toggle.addEventListener("click", () => (running ? stop() : start()));

  const wrap = morse.el("span", { class: "focus-timer" }, label, toggle);
  el.prepend(wrap);
});
